$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$modulePath = Join-Path $pkg "ahos\opportunity_intake.py"
$testPath = Join-Path $pkg "tests\test_jsonl_unicode_records.py"
$python = Join-Path $root ".venv\Scripts\python.exe"
$liveStore = Join-Path $root "runtime\live_intake\public_candidates.jsonl"

if (-not (Test-Path $modulePath)) { throw "opportunity_intake.py not found." }
if (-not (Test-Path $python)) { throw "Python venv not found: $python" }

Copy-Item $modulePath "$modulePath.bak" -Force
if (Test-Path $testPath) { Copy-Item $testPath "$testPath.bak" -Force }

[IO.File]::WriteAllBytes($modulePath, [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($testPath, [Convert]::FromBase64String(""))

Write-Host "=== AHOS JSONL READER FIX ==="
Write-Host "Fixing Unicode record-separator handling."
Write-Host "Running full AHOS tests (NO network, NO OpenAI API calls)..."

$oldPythonPath = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg
    & $python -m pytest -q
    $testExit = $LASTEXITCODE
} finally {
    Pop-Location
    $env:PYTHONPATH = $oldPythonPath
}

if ($testExit -ne 0) {
    Copy-Item "$modulePath.bak" $modulePath -Force
    if (Test-Path "$testPath.bak") {
        Copy-Item "$testPath.bak" $testPath -Force
    } else {
        Remove-Item $testPath -Force -ErrorAction SilentlyContinue
    }
    throw "Tests failed; previous implementation restored."
}

Remove-Item "$modulePath.bak" -Force
Remove-Item "$testPath.bak" -Force -ErrorAction SilentlyContinue

if (Test-Path $liveStore) {
    Write-Host ""
    Write-Host "Checking existing live candidate store..."
    $check = @'
from pathlib import Path
from ahos.opportunity_intake import OpportunityCandidateStore
path = Path(r"__LIVE_STORE__")
items = OpportunityCandidateStore(path).all()
print("LIVE STORE PARSE: PASS (%d records)" % len(items))
'@
    $check = $check.Replace("__LIVE_STORE__", $liveStore.Replace("\", "\\"))
    $oldPythonPath = $env:PYTHONPATH
    try {
        $env:PYTHONPATH = $pkg
        $check | & $python -
        if ($LASTEXITCODE -ne 0) { throw "Existing live store still has a physical JSON corruption." }
    } finally {
        $env:PYTHONPATH = $oldPythonPath
    }
}

git -C $ws add ahos_core/ahos/opportunity_intake.py ahos_core/tests/test_jsonl_unicode_records.py
git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" commit -m "fix(ahos): parse JSONL by physical record boundaries"
if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

git -C $ws push origin HEAD
if ($LASTEXITCODE -ne 0) { throw "git push failed." }

Write-Host ""
Write-Host "=== JSONL FIX COMPLETE ==="
Write-Host "Full AHOS tests: PASS"
Write-Host "Git push: PASS"
Write-Host "Network calls during fix: 0"
Write-Host "OpenAI API calls: 0"
